import json,shutil,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=Path.home()/'Documents/Cabinet-Inventory/preview'
audit=json.loads((ROOT/'review/audit.json').read_text());byid={r['id']:r for r in audit['products']}
(OUT/'review/audit.json').write_text(json.dumps(audit));shutil.copyfile(ROOT/'review/audit.csv',OUT/'review/audit.csv')
p=OUT/'catalog.json';catalog=json.loads(p.read_text())
for row in catalog['products']:row['audit']=byid[row['id']]
p.write_text(json.dumps(catalog))
p=OUT/'index.html';s=p.read_text();s=s.replace('<h1>Cabinet inventory</h1>','<h1>Cabinet inventory · reviewed drafts</h1>')
if 'id="review-status"' not in s:s=s.replace('<label for="family">','<label for="review-status">Review result</label><select id="review-status"><option value="">All draft models</option><option value="correction_required">Corrections required</option><option value="draft_visual_limitations">Visual limitations only</option></select><label for="family">')
if 'id="review-findings"' not in s:s=s.replace('<div class="presentation-controls"','<section style="border:1px solid #b58134;background:#fff6e6;padding:14px;border-radius:8px;margin:15px 0"><b id="review-heading">Draft — not approved for customer publication</b><ul id="review-findings"></ul><a href="/review/">Open full review report</a> · <a id="comparison" target="_blank">Source/model comparison</a></section><div class="presentation-controls"')
s=s.replace('Browse 1,734 dimensioned OPPEIN and Blue Valley models.','Browse 1,734 draft OPPEIN and Blue Valley models. The review found source and model issues; these are not individually approved products.')
if 'id="interior"' not in s:s=s.replace('<button id="reset">','<button id="interior">Show interior</button><button id="reset">')
p.write_text(s)
p=OUT/'library.js';s=p.read_text()
if "$('review-status').onchange" not in s:
 s=s.replace("$('brand').onchange=filter;","$('review-status').onchange=filter;$('brand').onchange=filter;")
 s=s.replace("(!family||p.family===family)&&", "(!family||p.family===family)&&(!$('review-status').value||p.audit.review_status===$('review-status').value)&&")
 s=s.replace("function select(p){active=p;", "function select(p){active=p;$('review-heading').textContent=p.audit.review_status==='correction_required'?'Corrections required — not approved':'Draft — visual limitations, not approved';$('review-findings').replaceChildren(...p.audit.findings.map(f=>{const li=document.createElement('li');li.textContent=f.detail;return li}));$('comparison').href='/review/sheet-'+Math.ceil(p.audit.representative_visual_group/16)+'.png';")
if 'function applyInterior()' not in s:
 s=s.replace("let stage;","let stage;let interior=false;function applyInterior(){stage?.cabinet?.traverse(o=>{if(/^(Door|Lower.?pantry.?door|Upper.?pantry.?door|Drawer.?front|False.?drawer.?front)/i.test(o.name))o.visible=!interior});stage?.render();} $('interior').onclick=()=>{interior=!interior;$('interior').textContent=interior?'Show fronts':'Show interior';applyInterior()};")
 s=s.replace('stage?.load(p);','stage?.load(p).then(applyInterior);')
 s=s.replace("p.audit.findings.map(f=>","[...p.audit.findings,...(p.audit.resolved_findings||[]).map(f=>({detail:'FIXED: '+f.code.replaceAll('_',' ').toLowerCase()}))].map(f=>")
p.write_text(s)
(OUT/'review/index.html').write_text('''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cabinet review · Reno Stars</title><style>body{font:15px/1.5 system-ui;margin:30px;color:#21303b;background:#f7f7f4}h1{margin-bottom:8px}section{background:white;padding:20px;border-radius:10px;margin:18px 0}input,select,button{font:inherit;padding:9px;margin:5px}table{width:100%;border-collapse:collapse;background:white}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd;vertical-align:top}td:nth-child(4){max-width:650px}a{color:#165571}.muted{color:#576771}</style><h1>Cabinet inventory review</h1><p><a href="/">Back to 3D preview</a> · <a href="audit.csv" download>Download review spreadsheet</a></p><section><b id="summary"></b><p>Every catalog record received an evidence/eligibility audit. Every GLB was independently measured from its serialized mesh vertices. The agent visually inspected 210 representative source/render comparisons; grouped size and finish variants were not individually photo-approved. Some supplier images are placeholders.</p><p>Cabinet-box finishes, sink clearances, specialty interiors and pantry proportions have been revised. Remaining dimension conflicts and visual approximations are listed per product. No products are approved for customer publication. Medusa importers now create drafts.</p></section><section><input id="search" placeholder="Search SKU, supplier or issue"><select id="status"><option value="">All records</option><option value="correction_required">Corrections required</option><option value="draft_visual_limitations">Visual limitations only</option><option value="specification_hold">Specification hold</option></select><span id="count"></span></section><table><thead><tr><th>Product</th><th>Review result</th><th>Evidence</th><th>Findings</th></tr></thead><tbody id="rows"></tbody></table><button id="more">Show more</button><script type="module">const data=await(await fetch('audit.json')).json();const s=data.summary;document.getElementById('summary').textContent=`${s.records} records · ${s.models} models · ${s.visual_groups_inspected} visual comparison groups · 0 approved`;let limit=60;const $=id=>document.getElementById(id);function render(){const q=$('search').value.toLowerCase(),status=$('status').value;const list=data.products.filter(p=>(!status||p.review_status===status)&&JSON.stringify([p.id,p.brand,p.findings]).toLowerCase().includes(q));$('count').textContent=list.length+' results';$('rows').replaceChildren(...list.slice(0,limit).map(p=>{const tr=document.createElement('tr');for(let i=0;i<4;i++)tr.append(document.createElement('td'));tr.children[0].textContent=p.brand+' / '+(p.supplier_sku||p.id);tr.children[1].textContent=p.review_status.replaceAll('_',' ');const source=document.createElement('a');source.href=p.source_url;source.target='_blank';source.textContent='Supplier';tr.children[2].append(source);if(p.model_url){const model=document.createElement('a');model.href='/?sku='+encodeURIComponent(p.id);model.textContent=' · View model';tr.children[2].append(model);const sheet=document.createElement('a');sheet.href='sheet-'+Math.ceil(p.representative_visual_group/16)+'.png';sheet.textContent=' · Comparison';sheet.target='_blank';tr.children[2].append(sheet)}tr.children[3].textContent=[...p.findings.map(f=>f.detail),...(p.resolved_findings||[]).map(f=>'FIXED: '+f.code)].join(' | ');return tr}));$('more').hidden=list.length<=limit}for(const id of ['search','status'])$(id).oninput=()=>{limit=60;render()};$('more').onclick=()=>{limit+=60;render()};render();</script></html>''')
print('Review preview updated')
